1	//! Tests for keyword abilities: flying, first strike, trample, deathtouch,
2	//! lifelink, vigilance, flash, reach, haste, defender, hexproof, intimidate.
3	
4	mod common;
5	
6	use common::*;
7	use mtg_engine::actions::{Action, Target};
8	use mtg_engine::cards::CardRegistry;
9	use mtg_engine::combat;
10	use mtg_engine::engine;
11	use mtg_engine::sba::check_state_based_actions_with_registry;
12	use mtg_engine::types::*;
13	
14	fn registry() -> CardRegistry {
15	    CardRegistry::with_all_cards()
16	}
17	
18	// ── Flying ──────────────────────────────────────────────────────────
19	
20	/// A creature with flying can only be blocked by creatures with flying or reach.
21	#[test]
22	fn flying_creature_cannot_be_blocked_by_ground_creature() {
23	    let reg = registry();
24	    let mut state = game_at_step(Step::DeclareBlockers, P0);
25	
26	    // P0's attacker: Abbey Griffin (2/2 flying)
27	    let attacker = named_creature(&mut state, &reg, "Abbey Griffin", P0);
28	
29	    // P1's blocker: vanilla ground creature
30	    let blocker = ready_creature(&mut state, P1, 3, 3);
31	
32	    assert!(!combat::can_block_attacker(&state, blocker, attacker, &reg),
33	        "Ground creature should not be able to block a flyer");
34	}
35	
36	/// A creature with flying CAN be blocked by another creature with flying.
37	#[test]
38	fn flyer_can_block_flyer() {
39	    let reg = registry();
40	    let mut state = game_at_step(Step::DeclareBlockers, P0);
41	
42	    let attacker = named_creature(&mut state, &reg, "Abbey Griffin", P0);
43	    let blocker = named_creature(&mut state, &reg, "Moon Heron", P1);
44	
45	    assert!(combat::can_block_attacker(&state, blocker, attacker, &reg),
46	        "Flyer should be able to block another flyer");
47	}
48	
49	/// A creature with reach can block a flyer.
50	#[test]
51	fn reach_can_block_flying() {
52	    let reg = registry();
53	    let mut state = game_at_step(Step::DeclareBlockers, P0);
54	
55	    let attacker = named_creature(&mut state, &reg, "Moon Heron", P0);
56	    let blocker = named_creature(&mut state, &reg, "Somberwald Spider", P1);
57	
58	    assert!(combat::can_block_attacker(&state, blocker, attacker, &reg),
59	        "Spider with reach should block a flyer");
60	}
61	
62	/// A non-flying attacker CAN be blocked by any creature (flying doesn't restrict ground blocks).
63	#[test]
64	fn ground_creature_can_be_blocked_normally() {
65	    let reg = registry();
66	    let mut state = game_at_step(Step::DeclareBlockers, P0);
67	    let attacker = ready_creature(&mut state, P0, 3, 3);
68	    let blocker = ready_creature(&mut state, P1, 2, 2);
69	
70	    assert!(combat::can_block_attacker(&state, blocker, attacker, &reg),
71	        "Ground creature should be blockable by anything");
72	}
73	
74	// ── Vigilance ───────────────────────────────────────────────────────
75	
76	/// Creatures with vigilance don't tap when attacking.
77	#[test]
78	fn vigilance_does_not_tap_on_attack() {
79	    let reg = registry();
80	    let mut state = game_at_step(Step::DeclareAttackers, P0);
81	
82	    let attacker = named_creature(&mut state, &reg, "Abbey Griffin", P0);
83	
84	    combat::declare_attackers(&mut state, &[(attacker, P1)], &reg);
85	
86	    assert!(!state.get_object(attacker).unwrap().tapped,
87	        "Creature with vigilance should not be tapped after attacking");
88	}
89	
90	/// A creature without vigilance still taps when attacking.
91	#[test]
92	fn non_vigilance_taps_on_attack() {
93	    let reg = registry();
94	    let mut state = game_at_step(Step::DeclareAttackers, P0);
95	    let attacker = ready_creature(&mut state, P0, 3, 3);
96	
97	    combat::declare_attackers(&mut state, &[(attacker, P1)], &reg);
98	
99	    assert!(state.get_object(attacker).unwrap().tapped,
100	        "Creature without vigilance should tap when attacking");
101	}
102	
103	// ── Defender ────────────────────────────────────────────────────────
104	
105	/// Creatures with defender cannot attack.
106	#[test]
107	fn defender_cannot_attack() {
108	    let reg = registry();
109	    let mut state = game_at_step(Step::DeclareAttackers, P0);
110	
111	    let defender = named_creature(&mut state, &reg, "Grave Bramble", P0);
112	
113	    let eligible = combat::eligible_attackers(&state, P0, &reg);
114	    assert!(!eligible.contains(&defender),
115	        "Creature with defender should not be eligible to attack");
116	}
117	
118	/// Creatures with defender CAN still block.
119	#[test]
120	fn defender_can_block() {
121	    let reg = registry();
122	    let mut state = game_at_step(Step::DeclareBlockers, P0);
123	
124	    let defender = named_creature(&mut state, &reg, "Grave Bramble", P1);
125	
126	    let eligible = combat::eligible_blockers(&state, P1, &reg);
127	    assert!(eligible.contains(&defender),
128	        "Creature with defender should still be eligible to block");
129	}
130	
131	// ── Haste ───────────────────────────────────────────────────────────
132	
133	/// Creatures with haste can attack the turn they enter (no summoning sickness).
134	#[test]
135	fn haste_overrides_summoning_sickness() {
136	    let reg = registry();
137	    let mut state = game_at_step(Step::DeclareAttackers, P0);
138	
139	    // Simulate a creature with haste that just entered (summoning_sick = true).
140	    // Use a creature object with haste keyword.
141	    // We don't have a haste creature card yet, so manually set the keyword.
142	    let creature = sick_creature(&mut state, P0, 3, 1);
143	    assert!(state.get_object(creature).unwrap().summoning_sick);
144	
145	    // Without haste, should not be eligible.
146	    let eligible = combat::eligible_attackers(&state, P0, &reg);
147	    assert!(!eligible.contains(&creature));
148	
149	    // Mark it as having haste via until-end-of-turn keyword.
150	    state.until_end_of_turn_keywords.push(
151	        mtg_engine::state::UntilEndOfTurnKeyword {
152	            target: creature,
153	            keyword: Keyword::Haste,
154	        }
155	    );
156	
157	    let eligible = combat::eligible_attackers(&state, P0, &reg);
158	    assert!(eligible.contains(&creature),
159	        "Creature with haste should be able to attack despite summoning sickness");
160	}
161	
162	// ── Hexproof ────────────────────────────────────────────────────────
163	
164	/// Creatures with hexproof can't be targeted by opponents' spells.
165	#[test]
166	fn hexproof_prevents_opponent_targeting() {
167	    let reg = registry();
168	    let mut state = game_at_step(Step::PrecombatMain, P0);
169	
170	    // P1 has Invisible Stalker on battlefield.
171	    let stalker = named_creature(&mut state, &reg, "Invisible Stalker", P1);
172	
173	    // P0 has Lightning Bolt in hand with mana to cast it.
174	    let _bolt = castable_spell(&mut state, &reg, "Lightning Bolt", P0);
175	
176	    let legal = engine::legal_actions(&state, &reg);
177	
178	    // There should NOT be a CastSpell action targeting the Stalker.
179	    let targets_stalker = legal.actions.iter().any(|a| {
180	        matches!(a, Action::CastSpell { targets, .. }
181	            if targets.iter().any(|t| matches!(t, Target::Object(id) if *id == stalker)))
182	    });
183	    assert!(!targets_stalker,
184	        "Lightning Bolt should not be able to target a hexproof creature controlled by opponent");
185	
186	    // But P0 CAN target their own hexproof creature (hexproof only stops opponents).
187	    let stalker_p0 = named_creature(&mut state, &reg, "Invisible Stalker", P0);
188	
189	    let legal2 = engine::legal_actions(&state, &reg);
190	    let targets_own = legal2.actions.iter().any(|a| {
191	        matches!(a, Action::CastSpell { targets, .. }
192	            if targets.iter().any(|t| matches!(t, Target::Object(id) if *id == stalker_p0)))
193	    });
194	    assert!(targets_own,
195	        "Should be able to target own hexproof creature");
196	}
197	
198	// ── Intimidate ──────────────────────────────────────────────────────
199	
200	/// Creatures with intimidate can only be blocked by artifact creatures or
201	/// creatures that share a color.
202	#[test]
203	fn intimidate_blocks_different_color() {
204	    let reg = registry();
205	    let mut state = game_at_step(Step::DeclareBlockers, P0);
206	
207	    // Spectral Rider is white with intimidate.
208	    let attacker = named_creature(&mut state, &reg, "Spectral Rider", P0);
209	    state.get_object_mut(attacker).unwrap().colors = vec![Color::White];
210	
211	    // Green creature can't block it.
212	    let green_blocker = ready_creature(&mut state, P1, 3, 3);
213	    state.get_object_mut(green_blocker).unwrap().colors = vec![Color::Green];
214	
215	    assert!(!combat::can_block_attacker(&state, green_blocker, attacker, &reg),
216	        "Green creature should not block a white intimidate creature");
217	
218	    // White creature CAN block it (shares color).
219	    let white_blocker = ready_creature(&mut state, P1, 2, 2);
220	    state.get_object_mut(white_blocker).unwrap().colors = vec![Color::White];
221	
222	    assert!(combat::can_block_attacker(&state, white_blocker, attacker, &reg),
223	        "White creature should be able to block a white intimidate creature");
224	}
225	
226	/// Artifact creatures can block creatures with intimidate regardless of color.
227	#[test]
228	fn artifact_creature_blocks_intimidate() {
229	    let reg = registry();
230	    let mut state = game_at_step(Step::DeclareBlockers, P0);
231	
232	    let attacker = named_creature(&mut state, &reg, "Spectral Rider", P0);
233	    state.get_object_mut(attacker).unwrap().colors = vec![Color::White];
234	
235	    // One-Eyed Scarecrow is an artifact creature.
236	    let blocker = named_creature(&mut state, &reg, "One-Eyed Scarecrow", P1);
237	
238	    assert!(combat::can_block_attacker(&state, blocker, attacker, &reg),
239	        "Artifact creature should be able to block an intimidate creature");
240	}
241	
242	// ── Deathtouch ──────────────────────────────────────────────────────
243	
244	/// Any damage from a deathtouch creature is lethal (SBA destroys the target).
245	#[test]
246	fn deathtouch_kills_with_one_damage() {
247	    let reg = registry();
248	    let mut state = game_at_step(Step::CombatDamage, P0);
249	
250	    // Typhoid Rats (1/1 deathtouch) attacks, blocked by a 5/5.
251	    let attacker = named_creature(&mut state, &reg, "Typhoid Rats", P0);
252	
253	    let blocker = ready_creature(&mut state, P1, 5, 5);
254	
255	    combat::declare_attackers(&mut state, &[(attacker, P1)], &reg);
256	    combat::declare_blockers(&mut state, &[(blocker, attacker)]);
257	    combat::deal_combat_damage(&mut state, &reg);
258	
259	    // Blocker took 1 damage from deathtouch source.
260	    assert_eq!(state.get_object(blocker).unwrap().damage_marked, 1);
261	    assert!(state.get_object(blocker).unwrap().dealt_deathtouch_damage);
262	
263	    // SBA should kill it despite only 1 damage on a 5-toughness creature.
264	    check_state_based_actions_with_registry(&mut state, Some(&reg));
265	    assert_eq!(state.get_object(blocker).unwrap().zone, Zone::Graveyard,
266	        "Creature dealt deathtouch damage should die regardless of toughness");
267	}
268	
269	/// Deathtouch with trample: only 1 damage needed per blocker, rest tramples through.
270	#[test]
271	fn deathtouch_trample_assigns_minimum() {
272	    let reg = registry();
273	    let mut state = game_at_step(Step::CombatDamage, P0);
274	
275	    // 5/5 with deathtouch + trample (simulated via EOT keywords).
276	    let attacker = ready_creature(&mut state, P0, 5, 5);
277	    state.until_end_of_turn_keywords.push(
278	        mtg_engine::state::UntilEndOfTurnKeyword { target: attacker, keyword: Keyword::Deathtouch }
279	    );
280	    state.until_end_of_turn_keywords.push(
281	        mtg_engine::state::UntilEndOfTurnKeyword { target: attacker, keyword: Keyword::Trample }
282	    );
283	
284	    let blocker = ready_creature(&mut state, P1, 2, 4);
285	
286	    combat::declare_attackers(&mut state, &[(attacker, P1)], &reg);
287	    combat::declare_blockers(&mut state, &[(blocker, attacker)]);
288	    combat::deal_combat_damage(&mut state, &reg);
289	
290	    // With deathtouch + trample: 1 damage assigned to blocker (lethal), 4 tramples through.
291	    assert_eq!(state.get_object(blocker).unwrap().damage_marked, 1);
292	    assert_eq!(state.get_player(P1).life, 16,
293	        "4 damage should trample to defending player (5 power - 1 deathtouch lethal)");
294	}
295	
296	// ── Lifelink ────────────────────────────────────────────────────────
297	
298	/// Lifelink: controller gains life equal to combat damage dealt.
299	#[test]
300	fn lifelink_gains_life_on_combat_damage() {
301	    let reg = registry();
302	    let mut state = game_at_step(Step::CombatDamage, P0);
303	
304	    let attacker = named_creature(&mut state, &reg, "Markov Patrician", P0);
305	
306	    combat::declare_attackers(&mut state, &[(attacker, P1)], &reg);
307	    combat::declare_blockers(&mut state, &[]);
308	    combat::deal_combat_damage(&mut state, &reg);
309	
310	    assert_eq!(state.get_player(P1).life, 17,
311	        "Defending player should take 3 damage");
312	    assert_eq!(state.get_player(P0).life, 23,
313	        "Attacking player should gain 3 life from lifelink");
314	}
315	
316	/// Lifelink also works when dealing damage to creatures in combat.
317	#[test]
318	fn lifelink_gains_life_from_creature_damage() {
319	    let reg = registry();
320	    let mut state = game_at_step(Step::CombatDamage, P0);
321	
322	    let attacker = named_creature(&mut state, &reg, "Markov Patrician", P0);
323	
324	    let blocker = ready_creature(&mut state, P1, 1, 4);
325	
326	    combat::declare_attackers(&mut state, &[(attacker, P1)], &reg);
327	    combat::declare_blockers(&mut state, &[(blocker, attacker)]);
328	    combat::deal_combat_damage(&mut state, &reg);
329	
330	    assert_eq!(state.get_player(P0).life, 23,
331	        "Should gain 3 life from lifelink even when blocked");
332	}
333	
334	// ── Trample ─────────────────────────────────────────────────────────
335	
336	/// Trample: excess damage carries over to the defending player.
337	#[test]
338	fn trample_excess_damage_to_player() {
339	    let reg = registry();
340	    let mut state = game_at_step(Step::CombatDamage, P0);
341	
342	    // 5/5 with trample.
343	    let attacker = ready_creature(&mut state, P0, 5, 5);
344	    state.until_end_of_turn_keywords.push(
345	        mtg_engine::state::UntilEndOfTurnKeyword { target: attacker, keyword: Keyword::Trample }
346	    );
347	
348	    let blocker = ready_creature(&mut state, P1, 2, 2);
349	
350	    combat::declare_attackers(&mut state, &[(attacker, P1)], &reg);
351	    combat::declare_blockers(&mut state, &[(blocker, attacker)]);
352	    combat::deal_combat_damage(&mut state, &reg);
353	
354	    // Blocker takes 2 (lethal), remaining 3 tramples to player.
355	    assert_eq!(state.get_object(blocker).unwrap().damage_marked, 2);
356	    assert_eq!(state.get_player(P1).life, 17,
357	        "3 excess damage should trample through to the player");
358	}
359	
360	/// Without trample, all damage goes to blocker even if overkill.
361	#[test]
362	fn without_trample_no_excess_damage() {
363	    let reg = registry();
364	    let mut state = game_at_step(Step::CombatDamage, P0);
365	
366	    let attacker = ready_creature(&mut state, P0, 5, 5);
367	    let blocker = ready_creature(&mut state, P1, 2, 2);
368	
369	    combat::declare_attackers(&mut state, &[(attacker, P1)], &reg);
370	    combat::declare_blockers(&mut state, &[(blocker, attacker)]);
371	    combat::deal_combat_damage(&mut state, &reg);
372	
373	    // All damage goes to blocker.
374	    assert_eq!(state.get_object(blocker).unwrap().damage_marked, 5);
375	    assert_eq!(state.get_player(P1).life, 20,
376	        "No damage should carry to player without trample");
377	}
378	
379	// ── First strike ────────────────────────────────────────────────────
380	
381	/// First strike creature deals damage first, killing a blocker before it can hit back.
382	#[test]
383	fn first_strike_kills_before_normal_damage() {
384	    let reg = registry();
385	    let mut state = game_at_step(Step::CombatDamage, P0);
386	
387	    // Voiceless Spirit: 2/1 flying, first strike
388	    let attacker = named_creature(&mut state, &reg, "Voiceless Spirit", P0);
389	
390	    // Blocker: Moon Heron 3/2 (would kill the 2/1 in simultaneous damage, but first strike prevents it)
391	    let blocker = named_creature(&mut state, &reg, "Moon Heron", P1);
392	
393	    combat::declare_attackers(&mut state, &[(attacker, P1)], &reg);
394	    combat::declare_blockers(&mut state, &[(blocker, attacker)]);
395	    combat::deal_combat_damage(&mut state, &reg);
396	
397	    // First strike deals 2 to Moon Heron (toughness 2), kills it in first strike step.
398	    // Then in normal damage step, Moon Heron is dead and doesn't deal damage back.
399	    // So Voiceless Spirit should survive.
400	    check_state_based_actions_with_registry(&mut state, Some(&reg));
401	
402	    assert_eq!(state.get_object(blocker).unwrap().zone, Zone::Graveyard,
403	        "Blocker should die from first strike damage");
404	    assert_eq!(state.get_object(attacker).unwrap().zone, Zone::Battlefield,
405	        "First striker should survive because blocker dies before dealing normal damage");
406	}
407	
408	// ── Flash ───────────────────────────────────────────────────────────
409	
410	/// Creatures with flash can be cast during the opponent's turn.
411	#[test]
412	fn flash_creature_castable_at_instant_speed() {
413	    let reg = registry();
414	    let mut state = game_at_step(Step::PrecombatMain, P0);
415	
416	    // Give P1 priority during P0's turn and an Ambush Viper in hand.
417	    state.priority_player = Some(P1);
418	    let viper = castable_spell(&mut state, &reg, "Ambush Viper", P1);
419	
420	    let legal = engine::legal_actions(&state, &reg);
421	
422	    let can_cast = legal.actions.iter().any(|a| {
423	        matches!(a, Action::CastSpell { object_id, .. } if *object_id == viper)
424	    });
425	    assert!(can_cast,
426	        "Ambush Viper with flash should be castable during opponent's main phase");
427	}
428	
429	/// A normal creature CANNOT be cast during the opponent's turn.
430	#[test]
431	fn normal_creature_not_castable_on_opponent_turn() {
432	    let reg = registry();
433	    let mut state = game_at_step(Step::PrecombatMain, P0);
434	
435	    state.priority_player = Some(P1);
436	    let rats = castable_spell(&mut state, &reg, "Typhoid Rats", P1);
437	
438	    let legal = engine::legal_actions(&state, &reg);
439	
440	    let can_cast = legal.actions.iter().any(|a| {
441	        matches!(a, Action::CastSpell { object_id, .. } if *object_id == rats)
442	    });
443	    assert!(!can_cast,
444	        "Normal creature should not be castable during opponent's turn");
445	}
446	
447	// ── Blocker validation with flying ──────────────────────────────────
448	
449	/// Declaring a ground creature as blocker of a flyer is filtered out.
450	#[test]
451	fn blocker_validation_rejects_ground_blocking_flyer() {
452	    let reg = registry();
453	    let mut state = game_at_step(Step::CombatDamage, P0);
454	
455	    let attacker = named_creature(&mut state, &reg, "Moon Heron", P0);
456	
457	    let blocker = ready_creature(&mut state, P1, 2, 2);
458	
459	    combat::declare_attackers(&mut state, &[(attacker, P1)], &reg);
460	    // Try to illegally block — should be filtered out.
461	    combat::declare_blockers_with_registry(&mut state, &[(blocker, attacker)], &reg);
462	    combat::deal_combat_damage(&mut state, &reg);
463	
464	    // The illegal block was rejected, so the flyer is unblocked → 3 damage to player.
465	    assert_eq!(state.get_player(P1).life, 17,
466	        "Illegal block should be filtered out; flyer deals damage unblocked");
467	}
468	
469	// ── has_keyword with aura-granted keywords ──────────────────────────
470	
471	/// Spectral Flight grants flying to the enchanted creature.
472	#[test]
473	fn aura_grants_keyword() {
474	    let reg = registry();
475	    let mut state = game_at_step(Step::PrecombatMain, P0);
476	
477	    let creature = ready_creature(&mut state, P0, 2, 2);
478	
479	    let sf = castable_spell(&mut state, &reg, "Spectral Flight", P0);
480	
481	    state = cast_and_resolve(&state, &reg, sf, vec![Target::Object(creature)]);
482	
483	    assert!(state.has_keyword(creature, Keyword::Flying, &reg),
484	        "Creature with Spectral Flight should have flying");
485	
486	    // Also check P/T bonus.
487	    assert_eq!(state.effective_power(creature, &reg), Some(4));
488	    assert_eq!(state.effective_toughness(creature, &reg), Some(4));
489	}
490	
